#include "TaskEditDialog.h"
namespace fg {
TaskEditDialog::TaskEditDialog(AppServices& s,std::optional<TaskId> id,QWidget* p):QDialog(p),services_(s),id_(id){setWindowTitle(id?QStringLiteral("编辑任务"):QStringLiteral("新建任务"));setProperty("role","dialog");setMinimumWidth(520);auto l=new QVBoxLayout(this);l->setContentsMargins(24,24,24,24);l->setSpacing(14);auto head=new QLabel(windowTitle());head->setProperty("role","dialogTitle");l->addWidget(head);auto form=new QFormLayout;title_=new QLineEdit;title_->setMinimumHeight(40);title_->setObjectName("taskEdit_title");note_=new QTextEdit;note_->setMaximumHeight(100);category_=new QComboBox;category_->addItems({QStringLiteral("学习"),QStringLiteral("工作"),QStringLiteral("生活")});priority_=new QComboBox;priority_->addItems({QStringLiteral("高"),QStringLiteral("中"),QStringLiteral("低")});priority_->setCurrentIndex(1);hasDue_=new QCheckBox(QStringLiteral("设置截止时间"));due_=new QDateTimeEdit(QDateTime::currentDateTime());due_->setCalendarPopup(true);due_->setEnabled(false);connect(hasDue_,&QCheckBox::toggled,due_,&QWidget::setEnabled);form->addRow(QStringLiteral("任务标题"),title_);form->addRow(QStringLiteral("备注"),note_);form->addRow(QStringLiteral("分类"),category_);form->addRow(QStringLiteral("优先级"),priority_);form->addRow(hasDue_,due_);l->addLayout(form);error_=new QLabel;error_->setWordWrap(true);error_->setProperty("role","error");l->addWidget(error_);
 if(id){auto r=s.task(*id);if(r.ok&&r.value){auto t=*r.value;title_->setText(t.title);note_->setPlainText(t.note);category_->setCurrentIndex(int(t.category));priority_->setCurrentIndex(int(t.priority));hasDue_->setChecked(t.dueAtUtc.has_value());if(t.dueAtUtc)due_->setDateTime(t.dueAtUtc->toLocalTime());}}
 initial_=state();auto row=new QHBoxLayout;row->addStretch();auto cancel=createButton("taskEdit.cancel",QStringLiteral("取消"),ButtonRole::Outline);auto save=createButton("taskEdit.save",QStringLiteral("保存"),ButtonRole::Primary);row->addWidget(cancel);row->addWidget(save);l->addLayout(row);connect(cancel,&QPushButton::clicked,this,&TaskEditDialog::reject);connect(save,&QPushButton::clicked,this,[this]{TaskDraft d;d.title=title_->text().trimmed();d.note=note_->toPlainText();d.category=TaskCategory(category_->currentIndex());d.priority=TaskPriority(priority_->currentIndex());if(hasDue_->isChecked())d.dueAtUtc=due_->dateTime().toUTC();auto r=services_.saveTask(d,id_);if(!r.ok){error_->setText(r.error.message);return;}emit taskSaved(r.value.id);accept();});}
QString TaskEditDialog::state()const{return title_->text()+"\n"+note_->toPlainText()+QString("|%1|%2|%3|").arg(category_->currentIndex()).arg(priority_->currentIndex()).arg(hasDue_->isChecked())+(hasDue_->isChecked()?due_->dateTime().toString(Qt::ISODate):QString());}
void TaskEditDialog::reject(){if(state()!=initial_){ConfirmDialog d(QStringLiteral("放弃修改"),QStringLiteral("放弃未保存的修改？"),QStringLiteral("放弃"),this);if(d.exec()!=QDialog::Accepted)return;}QDialog::reject();}
}
